insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values
('b2law-grammar','Zwracam się z prośbą ___ przesłanie kopii decyzji.','["o","od","do"]',0,'Prośba o + винительный называет предмет просьбы.',0),
('b2law-grammar','Wnioskodawca odwołał się ___ decyzji urzędu.','["od","o","z"]',0,'Odwołać się od требует родительного падежа.',1),
('b2law-grammar','Rodzina ubiega się ___ świadczenie mieszkaniowe.','["o","na","do"]',0,'Ubiegamy się o что-либо — устойчивое управление.',2),
('b2law-grammar','___ z regulaminem odpowiedź powinna zostać wysłana w ciągu 30 dni.','["Zgodnie","Zgodny","Zgodność"]',0,'Официальная связка zgodnie z вводит основание правила.',3),
('b2law-grammar','Составьте: Прошу повторно рассмотреть дело на основании приложенных документов.','["Proszę o ponowne rozpatrzenie sprawy na podstawie załączonych dokumentów.","Proszę ponownie sprawę rozpatrzyć na podstawa załączniki.","Wnoszę od dokumentów dla sprawa ponowna."]',0,'Proszę o требует отглагольного существительного, na podstawie — родительного.',4),
('b2law-grammar','Составьте: В связи с отсутствием ответа я подаю жалобу на бездействие органа.','["W związku z brakiem odpowiedzi składam skargę na bezczynność organu.","W związku brak odpowiedź skargę od organ składa.","Bez odpowiedzi organu odwołuję skargą do bezczynność."]',0,'W związku z требует творительного, skarga na — винительного.',5),
('b2law-quiz','Co należy dołączyć do pisma, jeśli wymaga tego procedura?','["załącznik","ustną obietnicę","reklamę"]',0,'Załącznik — документ, приложенный к обращению.',0),
('b2law-quiz','Od decyzji można się ___.','["odwołać","ubiegać","załączać o"]',0,'Нормативное сочетание — odwołać się od decyzji.',1),
('b2law-quiz','Która forma jest odpowiednia w oficjalnym piśmie?','["Zwracam się z prośbą o wyjaśnienie.","Hej, ogarnijcie to.","No i co z tym?"]',0,'Первая формула нейтральна, точна и вежлива.',2),
('b2law-quiz','Urząd działa ___ ustawy.','["na podstawie","na podstawę","podstawą od"]',0,'Na podstawie + родительный вводит правовое основание.',3),
('b2law-quiz','Co zawiera uzasadnienie decyzji?','["powody i podstawę rozstrzygnięcia","wyłącznie adres urzędu","reklamę usługi"]',0,'Обоснование объясняет фактические и правовые причины.',4),
('b2law-quiz','Ubiegam się ___ wydanie zaświadczenia.','["o","od","w"]',0,'Ubiegam się o + винительный.',5),
('b2law-quiz','Termin upływa, czyli ___.','["kończy się czas na wykonanie czynności","sprawa jest zawsze wygrana","przepis znika"]',0,'Upływ terminu означает окончание установленного срока.',6),
('b2law-quiz','Co pomaga skutecznie sformułować wniosek?','["konkretne żądanie, podstawa i załączniki","emocjonalne oskarżenia","brak danych kontaktowych"]',0,'Структурированное обращение позволяет органу проверить требование.',7),
('b2law-quiz','W związku ___ zmianą adresu proszę o aktualizację danych.','["ze","od","dla"]',0,'Перед сочетанием согласных употребляется w związku ze + творительный.',8),
('b2law-quiz','Kto rozpatruje sprawę?','["właściwy organ lub instytucja","dowolny sklep","wyłącznie sąsiad"]',0,'Дело рассматривает компетентный орган.',9),
('b2law-reading-check','Ile dni miała Marta na odwołanie?','["Czternaście","Trzydzieści","Dziesięć"]',0,'Срок в разъяснении составлял 14 дней.',0),
('b2law-reading-check','Dlaczego decyzja była odmowna?','["Urząd uznał, że brakowało załącznika","Marta przekroczyła termin wniosku","Nie podała adresu"]',0,'В обосновании указали отсутствие документа о доходе.',1),
('b2law-reading-check','Jaki dowód miała Marta?','["Elektroniczne potwierdzenie wysłania pliku","Nagranie rozmowy sąsiada","Paragon ze sklepu"]',0,'Платформа сохранила подтверждение отправки.',2),
('b2law-reading-check','Czego zażądała w odwołaniu?','["Ponownego rozpatrzenia i zmiany decyzji","Zmiany pracownika","Usunięcia regulaminu"]',0,'Просьба сформулирована прямо в третьем абзаце.',3),
('b2law-reading-check','Dlaczego unikała ocen pracownika?','["Chciała skupić pismo na faktach","Nie znała numeru sprawy","Nie mogła dodać załączników"]',0,'Официальное письмо должно помогать проверить факты.',4),
('b2law-reading-check','Co warto sprawdzić przed wysłaniem pisma?','["Organ, termin i sposób doręczenia","Tylko kolor dokumentu","Popularność instytucji"]',0,'Эти три элемента перечислены в выводе.',5);
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('b2law-odwolanie-od-decyzji','b2-law-civic','Odwołanie, które można było rozpatrzyć','Как жительница проверила срок, основание и структуру официального обращения','B2',12,'⚖️','["Marta złożyła wniosek o świadczenie mieszkaniowe, lecz po miesiącu otrzymała decyzję odmowną. Dokument zawierał pouczenie, że może wnieść odwołanie w ciągu czternastu dni od doręczenia. Kobieta najpierw sprawdziła datę odbioru, ponieważ przekroczenie terminu mogłoby utrudnić dalsze postępowanie.","W uzasadnieniu urząd wskazał brak jednego załącznika potwierdzającego dochód. Marta miała jednak elektroniczne potwierdzenie, że dokument został przesłany razem z wnioskiem. Zgodnie z regulaminem platformy takie potwierdzenie stanowi dowód złożenia pliku, dlatego postanowiła odwołać się od decyzji.","Pismo rozpoczęła od danych swoich i właściwego organu. Następnie napisała: „Wnoszę o ponowne rozpatrzenie sprawy oraz zmianę decyzji”. W związku z rozbieżnością między uzasadnieniem a potwierdzeniem wysyłki opisała kolejność zdarzeń, podała numer sprawy i powołała się na załączony dowód. Unikała ocen pracownika, bo celem było wyjaśnienie faktów.","Do odwołania ponownie dołączyła dokument o dochodzie, kopię decyzji i potwierdzenie wysyłki. Urząd miał obowiązek przekazać pismo do właściwej jednostki albo samodzielnie zmienić rozstrzygnięcie. Po dziesięciu dniach Marta otrzymała informację, że jej uprawnienie do świadczenia zostanie ponownie ocenione.","Ta sytuacja pokazuje, że oficjalny styl nie musi być skomplikowany. Skuteczne pismo jasno określa żądanie, wskazuje podstawę, porządkuje fakty i wymienia załączniki. Przed wysłaniem warto też sprawdzić właściwość organu, termin oraz sposób doręczenia. Dzięki temu instytucja może rozpatrzyć sprawę, zamiast prosić o uzupełnienie podstawowych danych."]','{"świadczenie":{"lemma":"świadczenie","translation":"пособие, выплата","part_of_speech":"существительное"},"odmowną":{"lemma":"odmowny","translation":"отказную","part_of_speech":"прилагательное"},"pouczenie":{"lemma":"pouczenie","translation":"разъяснение порядка обжалования","part_of_speech":"существительное"},"wnieść odwołanie":{"lemma":"wnieść odwołanie","translation":"подать апелляцию","part_of_speech":"устойчивое выражение"},"doręczenia":{"lemma":"doręczenie","translation":"вручения","part_of_speech":"существительное"},"przekroczenie":{"lemma":"przekroczenie","translation":"пропуск, превышение","part_of_speech":"существительное"},"postępowanie":{"lemma":"postępowanie","translation":"производство, процедура","part_of_speech":"существительное"},"uzasadnieniu":{"lemma":"uzasadnienie","translation":"обосновании","part_of_speech":"существительное"},"załącznika":{"lemma":"załącznik","translation":"приложения","part_of_speech":"существительное"},"stanowi":{"lemma":"stanowić","translation":"представляет собой","part_of_speech":"глагол"},"rozbieżnością":{"lemma":"rozbieżność","translation":"расхождением","part_of_speech":"существительное"},"powołała się":{"lemma":"powołać się","translation":"сослалась","part_of_speech":"глагол"},"kolejność zdarzeń":{"lemma":"kolejność zdarzeń","translation":"последовательность событий","part_of_speech":"словосочетание"},"rozstrzygnięcie":{"lemma":"rozstrzygnięcie","translation":"решение по существу","part_of_speech":"существительное"},"uprawnienie":{"lemma":"uprawnienie","translation":"право","part_of_speech":"существительное"},"żądanie":{"lemma":"żądanie","translation":"требование","part_of_speech":"существительное"},"właściwość organu":{"lemma":"właściwość organu","translation":"компетенция органа","part_of_speech":"словосочетание"},"uzupełnienie":{"lemma":"uzupełnienie","translation":"дополнение","part_of_speech":"существительное"},"obowiązek":{"lemma":"obowiązek","translation":"обязанность","part_of_speech":"существительное"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-30","comprehension_lesson_id":"b2law-reading-check"}',41,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
